from common import T

# --- Pulmonary segmental arteries and veins (patterned) ------------------------------
SEG = {
    "Apical": ("apikal", "apicalis"), "Posterior": ("posterior", "posterior"), "Anterior": ("anterior", "anterior"),
    "Lateral": ("lateral", "lateralis"), "Medial": ("medial", "medialis"), "Superior": ("superior", "superior"),
    "Anterior basal": ("anterior bazal", "basalis anterior"), "Lateral basal": ("lateral bazal", "basalis lateralis"),
    "Medial basal": ("medial bazal", "basalis medialis"), "Posterior basal": ("posterior bazal", "basalis posterior"),
    "Superior lingular": ("üst lingular", "lingularis superior"), "Inferior lingular": ("alt lingular", "lingularis inferior"),
}
for side_en, side_tr, side_la in [("right", "sağ", "dextri"), ("left", "sol", "sinistri")]:
    for key, (tr, la) in SEG.items():
        if "lingular" in key:
            name = f"{key} artery of {side_en} lung"
        else:
            name = f"{key} segmental artery of {side_en} lung"
        T(name, f"{side_tr.capitalize()} akciğer {tr} segment arteri", f"Arteria segmentalis {la} pulmonis {side_la}",
          f"Pulmoner arterin {side_tr} akciğerdeki {tr} segmente giden dalı; segmental bronşa eşlik ederek oksijensiz kanı alveollere taşır.")
for side_en, side_tr, side_la in [("right", "Sağ", "dextri"), ("left", "Sol", "sinistri")]:
    for key, tr, la in [("Superior lobar artery", "üst lob arteri", "Arteria lobaris superior"), ("Middle lobar artery", "orta lob arteri", "Arteria lobaris media"),
                        ("Inferior lobar artery", "alt lob arteri", "Arteria lobaris inferior")]:
        T(f"{key} of {side_en} lung", f"{side_tr} akciğer {tr}", f"{la} pulmonis {side_la}", f"Pulmoner arterin {side_tr.lower()} akciğerdeki {tr.split(' arteri')[0]}una giden dalı.")
    for key, tr, la in [("Apical vein", "apikal ven", "apicalis"), ("Posterior vein", "posterior ven", "posterior"), ("Anterior vein", "anterior ven", "anterior"),
                        ("Lateral vein", "lateral ven", "lateralis"), ("Medial vein", "medial ven", "medialis"), ("Superior vein", "superior ven", "superior"),
                        ("Superior basal vein", "üst bazal ven", "basalis superior"), ("Inferior basal vein", "alt bazal ven", "basalis inferior"),
                        ("Apicoposterior vein", "apikoposterior ven", "apicoposterior"), ("Lingular vein", "lingular ven", "lingularis"),
                        ("Superior lingular vein", "üst lingular ven", "lingularis superior"), ("Inferior lingular vein", "alt lingular ven", "lingularis inferior")]:
        T(f"{key} of {side_en} lung", f"{side_tr} akciğer {tr}", f"Vena {la} pulmonis {side_la}",
          "Segmentler arası düzlemde seyrederek oksijenli kanı pulmoner venlere taşıyan dal; segmentektomide segment sınırlarının işaretidir.")

